export class CliExit extends Error {
  constructor(code, stream, output) {
    super(`CLI exited with status ${code}`);
    this.name = 'CliExit';
    this.code = code;
    this.stream = stream;
    this.output = output;
  }
}

function looksLikeOptionToken(token) {
  return typeof token === 'string' && token.length > 1 && token.startsWith('-');
}

