  const optionLines = optionDefinitions.map((definition) => `  ${definition.flag} ${definition.metavar}\n`).join('');

  return `${formatUsage(programName, optionDefinitions)}\noptions:\n  -h, --help  show this help message and exit\n${optionLines}`;
}

function createError(programName, optionDefinitions, message) {
  return new CliExit(2, 'stderr', `${formatUsage(programName, optionDefinitions)}${programName}: error: ${message}\n`);
}

function parseOptionValue(rawValue, definition, programName, optionDefinitions) {
