    const codePoint = character.codePointAt(0);

    if (character === '\\') {
      rendered += '\\\\';
      continue;
    }

    if (character === "'") {
      rendered += "\\'";
      continue;
    }

    if (character === '\n') {
      rendered += '\\n';
      continue;
    }

    if (character === '\r') {
      rendered += '\\r';
      continue;
    }

    if (character === '\t') {
      rendered += '\\t';
      continue;
    }

    if (character === '\v') {
      rendered += '\\x0b';
      continue;
    }

    if (character === '\f') {
      rendered += '\\x0c';
      continue;
    }

    if (codePoint >= 0x20 && codePoint <= 0x7e) {
      rendered += character;
      continue;
    }

    if (codePoint <= 0xff) {
      rendered += `\\x${codePoint.toString(16).padStart(2, '0')}`;
      continue;
    }

    if (codePoint <= 0xffff) {
      rendered += `\\u${codePoint.toString(16).padStart(4, '0')}`;
      continue;
    }

    rendered += `\\U${codePoint.toString(16).padStart(8, '0')}`;
  }

  rendered += "'";
  return rendered;
}

export function formatPythonBytesRepr(value) {
  return `b${formatPythonStringLiteral(value)}`;
}

export function formatPythonInteger(value) {
  return value.toString();
}
